using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EvenOddSoulHeatCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/EvenOddSoulHeatCustomDescription", order = 0)]
public class EvenOddSoulHeatCustomDescription : MultipleActionCustomDescription
{
	private const string andIncreasesSoulHeatHeatID = "AndIncreasesSoulHeat";

	[SerializeField]
	private SoulHeatBasedCustomDescription soulHeatBasedCustomDescription;

	private string andIncreasesSoulHeatHeatLocalized => ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("AndIncreasesSoulHeat");

	private string dontBreakChantingID => ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(soulHeatBasedCustomDescription.DontBreakChantingID);

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		EvenOddSoulHeatAction evenOddSoulHeatAction = battleAction as EvenOddSoulHeatAction;
		string text = evenOddSoulHeatAction.EvenAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		if (evenOddSoulHeatAction.EclipseBlastCorruptionIncreaseSoulHeat)
		{
			if (!LanguagesIndexes.IsCurrentLanguageKorean())
			{
				text = text.RemoveLast();
			}
			text = text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + andIncreasesSoulHeatHeatLocalized;
		}
		string text2 = evenOddSoulHeatAction.OddAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		if (evenOddSoulHeatAction.SandshapingIncreaseSoulHeat)
		{
			text2 = text2.RemoveLast();
			text2 = text2 + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + andIncreasesSoulHeatHeatLocalized;
		}
		string[] array = base.localizationManager.GetLocalizedEvenOddSoulHeat().Split('\n');
		array[1] = array[1].Replace("{1}", "{0}");
		text = Smart.Format(array[0], text);
		text2 = Smart.Format(array[1], text2);
		if (IsAddHighlight())
		{
			if (evenOddSoulHeatAction.Counter % 2 == 0)
			{
				text = GetHighlightedDescription(text);
			}
			else
			{
				text2 = GetHighlightedDescription(text2);
			}
		}
		return text + "\n" + text2;
	}
}
